// Chord-search regression wall.
//
// Table-driven coverage of the professional notation matrix from the WS13 audit
// (docs/superpowers/ws13-chord-search-audit.md). Every row was generated by
// EXECUTING the real parser, never by reading code. Three blocks:
//   1. POSITIVE  — notation → exact ChordQuality (incl. accidental roots, case,
//                  unicode, slash chords, single-word verbal, legit-complex).
//   2. NEGATIVE  — garbage / ambiguous input that must NOT parse (returns null).
//   3. COMPLEX   — chords only the algorithmic fallback handles; must still parse
//                  (non-null) so the garbage gate never over-rejects.
//
// If a future change regresses any cell, this wall fails.

import { describe, it, expect } from 'vitest';
import { parseChordSymbol } from '../chordParser';
import type { ChordQuality } from '../../types/music';

