// ── 2. NEGATIVE: must NOT parse ────────────────────────────────────────────
const NEGATIVE: string[] = [
  'C0',        // zero is NOT half-diminished — ambiguous, deliberate exclusion
  'Cx',        // garbage suffix
  'Cmaj77',    // invalid double-seven
  'H7',        // German H — unsupported (deliberate)
  'hello world',
  'Cblah',     // garbage word (also guards Cb-root + "lah" leftover)
  'C7b',       // dangling accidental, no degree
  '7',         // no root
  'Zmaj7',     // invalid root letter
  'Czzz', 'C123', 'Cqwerty', 'Cmaj7xyz', 'Ch', 'C55', 'C25',
];

// ── 3. COMPLEX: must still parse (non-null) ────────────────────────────────
// Mostly algorithmic-path chords. WS14 promoted Cmaj9#11 / C7b13 / C7#11 to
// named qualities (now asserted in the CANONICAL block below); the remainder
// still resolve through the lenient algorithmic builder.
const COMPLEX_MUST_PARSE: string[] = [
  'Cmaj7#11', 'G7b9#11', 'Dm9b5', 'C7#9#11', 'Am9', 'Cm11b5', 'C7b9b13',
  'Cadd#11', 'Cm(add9)', 'C7sus4b9', 'Cmaj7#5', 'C6/9', 'Bb7sus4', 'Am(add9)', 'Fmaj13#11',
  'C9sus4', 'C13#11', 'C7#9b13', 'Cm7add11', 'Cmaj7b5', 'Co7', 'C-7b5',
  'D7alt', 'C13b9', 'Cmaj13', 'C7b5#9', 'Cdim(maj7)',
];

describe('chord-search matrix — positive (notation → quality)', () => {
  it.each(POSITIVE)('%s → %s', (notation, expected) => {
    const r = parseChordSymbol(notation);
    expect(r, `"${notation}" should parse`).not.toBeNull();
    expect(r!.quality, `"${notation}" quality`).toBe(expected);
  });
});

describe('chord-search matrix — negative (must NOT parse)', () => {
  it.each(NEGATIVE)('%s → null', (notation) => {
    expect(parseChordSymbol(notation), `"${notation}" should be rejected`).toBeNull();
  });
});

describe('chord-search matrix — complex (algorithmic, must still parse)', () => {
  it.each(COMPLEX_MUST_PARSE)('%s parses', (notation) => {
    expect(parseChordSymbol(notation), `"${notation}" must still parse`).not.toBeNull();
  });
});

describe('chord-search matrix — every ChordQuality reachable by a canonical symbol', () => {
  // The engine defines 50 chord qualities (CHORD_FORMULAS / CHORD_SYMBOLS /
  // CHORD_QUALITY_NAMES all have 50 keys). WS14 closed three taxonomy gaps that
  // previously fell to the algorithmic path: major9sharp11, dominant7sharp11,
  // dominant7flat13. This guards that the parser can produce EACH from at least
  // one symbol (the canonical/primary one). dominant7sharp5 has no distinct
  // primary symbol — bare 7#5 collapses to augmented7 (same notes) — so it is
  // reached via '+'.
  const CANONICAL: Array<[string, ChordQuality]> = [
    ['C', 'major'], ['Cm', 'minor'], ['Cdim', 'diminished'], ['Caug', 'augmented'],
    ['C6', 'major6'], ['Cm6', 'minor6'], ['Cmaj7', 'major7'], ['Cm7', 'minor7'],
    ['C7', 'dominant7'], ['Cdim7', 'diminished7'], ['Cm7b5', 'half_diminished7'],
    ['Caug7', 'augmented7'], ['Csus2', 'sus2'], ['Csus4', 'sus4'], ['Cadd9', 'add9'],
    ['CmMaj7', 'minor_major7'], ['C5', 'power'], ['C7sus4', 'dominant7sus4'],
    ['Cmaj9', 'major9'], ['Cm9', 'minor9'], ['C9', 'dominant9'],
    ['C7b9', 'dominant7flat9'], ['C7#9', 'dominant7sharp9'], ['C7b5', 'dominant7flat5'],
    ['C7+', 'dominant7sharp5'], ['C7alt', 'dominant7alt'], ['C11', 'dominant11'],
    ['Cmaj11', 'major11'], ['Cm11', 'minor11'], ['C9#11', 'dominant9sharp11'],
    ['C13', 'dominant13'], ['Cmaj13', 'major13'], ['Cm13', 'minor13'],
    ['C13b9', 'dominant13flat9'], ['Cadd11', 'add11'], ['C6/9', 'six_nine'],
    ['Cm6/9', 'minor_six_nine'], ['C9sus4', 'dominant9sus4'], ['Csus2sus4', 'sus2sus4'],
    ['Cmaj7#5', 'augmented_major7'], ['Cmaj7b5', 'major7flat5'],
    ['Cmaj7#11', 'major7sharp11'], ['Cdim(maj7)', 'diminished_major7'],
    ['C7#5b9', 'dominant7sharp5flat9'], ['C7b5b9', 'dominant7flat5flat9'],
    ['C7#5#9', 'dominant7sharp5sharp9'], ['C7b5#9', 'dominant7flat5sharp9'],
    // WS14: three closed taxonomy gaps, each now reached by its canonical symbol.
    ['Cmaj9#11', 'major9sharp11'], ['C7#11', 'dominant7sharp11'],
    ['C7b13', 'dominant7flat13'],
  ];

  it.each(CANONICAL)('%s → %s', (symbol, quality) => {
    expect(parseChordSymbol(symbol)?.quality, `${symbol}`).toBe(quality);
  });

  it('covers all 50 engine ChordQuality values via the canonical map', () => {
    // Locks the count so a dropped row is caught. All 50 qualities are reached
    // exactly by their canonical symbol (verified by the audit harness).
    const covered = new Set(CANONICAL.map(([, q]) => q));
    expect(covered.size).toBe(50);
  });
});

describe('chord-search matrix — iOS ordinal autocorrect (º for °)', () => {
  // Typing the degree sign ° (U+00B0) on an iPhone frequently autocorrects to
  // the masculine ordinal º (U+00BA). Both that and the ring operator ∘ (U+2218)
  // normalize to ° so diminished chords still resolve. A leading "m" before the
  // symbol stays a reject (genuinely malformed: "G minor diminished 7").
  const ORDINAL: Array<[string, ChordQuality | null]> = [
    ['Cº', 'diminished'], ['Cº7', 'diminished7'], ['F#º7', 'diminished7'],
    ['Dbº', 'diminished'], ['C∘', 'diminished'], ['C∘7', 'diminished7'],
    ['Gmº7', null],
    // Redundant minor before the half-dim sign (ø already implies minor) resolves;
    // plain minor 7 is untouched.
    ['Bbmø7', 'half_diminished7'], ['Cmø', 'half_diminished7'], ['Bbm7', 'minor7'],
  ];
  it.each(ORDINAL)('%s → %s', (symbol, quality) => {
    expect(parseChordSymbol(symbol)?.quality ?? null, `${symbol}`).toBe(quality);
  });
});
